// Extract the plain-text body from the Gmail message payload.
// n8n's Gmail node returns the full RFC 2822 message in $json.payload.

const item = $input.item.json;

// Helper: decode base64url
function decodeBase64(str) {
  if (!str) return '';
  // Replace URL-safe chars and pad
  const b64 = str.replace(/-/g, '+').replace(/_/g, '/');
  try {
    return Buffer.from(b64, 'base64').toString('utf-8');
  } catch(e) {
    return '';
  }
}

// Recursively search MIME parts for text/plain body
function findPlainText(part) {
  if (!part) return '';
  if (part.mimeType === 'text/plain' && part.body && part.body.data) {
    return decodeBase64(part.body.data);
  }
  if (part.mimeType === 'text/html' && part.body && part.body.data) {
    // Strip HTML tags as fallback
    const html = decodeBase64(part.body.data);
    return html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  }
  if (part.parts && Array.isArray(part.parts)) {
    for (const child of part.parts) {
      const text = findPlainText(child);
      if (text) return text;
    }
  }
  return '';
}

const payload = item.payload || {};
let body = findPlainText(payload);

// Fallback to snippet if body extraction failed
if (!body && item.snippet) {
  body = item.snippet;
}

// Extract sender from headers
const headers = (payload.headers || []);
const fromHeader = headers.find(h => h.name && h.name.toLowerCase() === 'from');
const sender = fromHeader ? fromHeader.value : 'unknown';

const subjectHeader = headers.find(h => h.name && h.name.toLowerCase() === 'subject');
const subject = subjectHeader ? subjectHeader.value : '';

return [{
  json: {
    messageId: item.id,
    sender: sender,
    subject: subject,
    body: body,
    bodyLength: body.length,
  }
}];

// Parse the output from email_url_filter.py
const output = $input.item.json.stdout || '';
const lines = output.split('\n');

const result = {
  result: '',
  rawUrls: 0,
  jobUrls: 0,
  duplicates: 0,
  added: 0,
  newUrls: [],
  rawOutput: output,
};

for (const line of lines) {
  if (line.startsWith('RESULT: '))      result.result     = line.slice(8).trim();
  if (line.startsWith('RAW_URLS: '))    result.rawUrls    = parseInt(line.slice(10));
  if (line.startsWith('JOB_URLS: '))    result.jobUrls    = parseInt(line.slice(10));
  if (line.startsWith('DUPLICATES: '))  result.duplicates = parseInt(line.slice(12));
  if (line.startsWith('ADDED: '))       result.added      = parseInt(line.slice(7));
  if (line.startsWith('NEW_URL: '))     result.newUrls.push(line.slice(9).trim());
}

return [{ json: result }];
